-- Declared foreign keys for equity module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('equity.dividends') IS NOT NULL AND to_regclass('equity.share_classes') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('equity.dividends') AND c.contype = 'f' AND a.attname = 'share_class_id'
    ) THEN
        ALTER TABLE equity.dividends ADD CONSTRAINT fk_dividends_share_class_id FOREIGN KEY (share_class_id) REFERENCES equity.share_classes (id) NOT VALID;
        BEGIN
            ALTER TABLE equity.dividends VALIDATE CONSTRAINT fk_dividends_share_class_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_dividends_share_class_id left NOT VALID: stored rows of equity.dividends reference missing rows';
        END;
    END IF;
END $$;

